import React, { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import api from '../services/api';

const ProductEdit = () => {
  const { id } = useParams(); // Если id есть, значит это редактирование
  const navigate = useNavigate();

  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [price, setPrice] = useState('');
  const [category, setCategory] = useState('');
  const [categories, setCategories] = useState([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    // Загружаем список категорий для селекта
    api.get('categories/')
      .then(res => setCategories(res.data.results || res.data))
      .catch(err => console.error('Ошибка загрузки категорий', err));

    // Если передан id, значит редактируем — подгружаем данные товара
    if (id) {
      setLoading(true);
      api.get(`products/${id}/`)
        .then(res => {
          setTitle(res.data.title);
          setDescription(res.data.description);
          setPrice(res.data.price);
          setCategory(res.data.category);
        })
        .catch(err => console.error('Ошибка загрузки товара', err))
        .finally(() => setLoading(false));
    }
  }, [id]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    const productData = { title, description, price, category };

    try {
      if (id) {
        // Редактирование
        await api.put(`products/${id}/`, productData);
      } else {
        // Создание
        await api.post('products/', productData);
      }
      navigate('/catalog');
    } catch (err) {
      console.error('Ошибка сохранения товара', err);
      alert('Не удалось сохранить товар. Проверьте данные.');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '80px' }}>Загрузка...</div>;
  }

  return (
    <div style={{ maxWidth: '600px', margin: '40px auto', padding: '40px', background: '#fff', borderRadius: '16px', boxShadow: '0 8px 24px rgba(0,0,0,0.06)', border: '1px solid #eaeaea' }}>
      <h2 style={{ marginBottom: '25px', color: '#1a1a1a' }}>
        {id ? 'Редактировать товар' : 'Создать товар'}
      </h2>
      
      <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
        <div>
          <label style={{ display: 'block', marginBottom: '8px', fontWeight: '600', color: '#444' }}>Название</label>
          <input 
            type="text" 
            value={title} 
            onChange={(e) => setTitle(e.target.value)} 
            required
            style={{ width: '100%', padding: '10px 14px', borderRadius: '8px', border: '1px solid #ced4da', boxSizing: 'border-box' }}
          />
        </div>

        <div>
          <label style={{ display: 'block', marginBottom: '8px', fontWeight: '600', color: '#444' }}>Категория</label>
          <select 
            value={category} 
            onChange={(e) => setCategory(e.target.value)} 
            required
            style={{ width: '100%', padding: '10px 14px', borderRadius: '8px', border: '1px solid #ced4da', boxSizing: 'border-box', background: '#fff' }}
          >
            <option value="">Выберите категорию</option>
            {categories.map(cat => (
              <option key={cat.id} value={cat.id}>{cat.name}</option>
            ))}
          </select>
        </div>

        <div>
          <label style={{ display: 'block', marginBottom: '8px', fontWeight: '600', color: '#444' }}>Цена (₾)</label>
          <input 
            type="number" 
            value={price} 
            onChange={(e) => setPrice(e.target.value)} 
            required
            style={{ width: '100%', padding: '10px 14px', borderRadius: '8px', border: '1px solid #ced4da', boxSizing: 'border-box' }}
          />
        </div>

        <div>
          <label style={{ display: 'block', marginBottom: '8px', fontWeight: '600', color: '#444' }}>Описание</label>
          <textarea 
            value={description} 
            onChange={(e) => setDescription(e.target.value)} 
            rows="5"
            required
            style={{ width: '100%', padding: '10px 14px', borderRadius: '8px', border: '1px solid #ced4da', boxSizing: 'border-box' }}
          />
        </div>

        <button 
          type="submit" 
          style={{ padding: '12px', background: '#F59E0B', color: '#1a1a1a', border: 'none', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer', fontSize: '16px' }}
        >
          {id ? 'Сохранить изменения' : 'Опубликовать товар'}
        </button>
      </form>
    </div>
  );
};

export default ProductEdit;
